// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.reasoningimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.ReasoningStepimport com.roshan.persona.persona.core.PersonaProfileimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Chain of Thought (Module 7 v2 — Step 7.4). * * Generates step-by-step reasoning using LLM — like OpenAI o1's visible * chain-of-thought, but transparent to the user. * * ## How it works * * 1. Build a persona-styled prompt: "Think step by step about [query]." * 2. Call LLM with the persona's temperature (Atlas=0.4 methodical, Aria=0.9 creative). * 3. Parse the response into [ReasoningStep] objects (thought → action → observation). * 4. Return the steps for [ReasoningEngine] to assemble into a [ReasoningTrace]. * * ## Adaptive depth (per Q5) * * The number of reasoning steps is adaptive: *  - Simple queries ("what time is it?") → [CognitiveConfig.minReasoningSteps] (3). *  - Complex queries ("should I buy a house?") → [CognitiveConfig.maxReasoningSteps] (10). *  - The LLM is prompted with the target step count. * * ## Reasoning step format * * The LLM returns steps in a structured format: * ``` * THOUGHT: Flights cost ₹3-5K, train costs ₹800. * ACTION: Checking train schedule. * OBSERVATION: Train departs 6 AM, arrives 2 PM. * CONFIDENCE: 0.85 * --- * THOUGHT: Train is much cheaper. ₹800 vs ₹3K saves ₹2.2K. * ... * ``` * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ReasoningEngine</a> */class ChainOfThought(    private val llm: ReasoningLlm,    private val config: CognitiveConfig = CognitiveConfig(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Generate chain-of-thought reasoning steps for [query].     *     * @param query the user's question or goal.     * @param persona the active persona (affects prompt style + LLM temperature).     * @param targetSteps the desired number of reasoning steps (adaptive).     * @param context additional context (memory recall, ambient snapshot).     * @return list of reasoning steps (3-10), or empty list if LLM fails.     */    suspend fun generate(        query: String,        persona: PersonaProfile,        targetSteps: Int = config.minReasoningSteps,        context: String = "",    ): List<ReasoningStep> = withContext(dispatcher) {        val clampedSteps = targetSteps.coerceIn(config.minReasoningSteps, config.maxReasoningSteps)        val prompt = buildPrompt(query, persona, clampedSteps, context)        val response = try {            llm.reason(prompt, persona.llmHyperparams.temperature)        } catch (t: Throwable) {            return@withContext emptyList()        }        parseSteps(response)    }    /**     * Build the chain-of-thought prompt for [persona].     *     * Persona style affects the prompt:     *  - Atlas: "Let us reason through this methodically, sir."     *  - Onyx: "Analyze. Be direct."     *  - Aria: "Let's think about this creatively!"     */    internal fun buildPrompt(        query: String,        persona: PersonaProfile,        targetSteps: Int,        context: String,    ): String {        val personaStyle = when (persona.id) {            "atlas" -> "Be methodical and precise. Use formal language."            "nova" -> "Be warm and conversational. Use everyday language."            "onyx" -> "Be terse and direct. No unnecessary words."            "sage" -> "Be gentle and thorough. Explain your reasoning."            "echo" -> "Be casual and friendly. Use simple language."            "vanguard" -> "Be tactical and concise. Focus on actionable steps."            "aria" -> "Be creative and enthusiastic. Think outside the box!"            "wraith" -> "Be minimal. Only essential reasoning."            "zenith" -> "Be calm and measured. Prioritize accuracy."            else -> "Think step by step."        }        val contextLine = if (context.isNotBlank()) "\nContext: $context\n" else ""        return """You are ${persona.displayName}. $personaStyleReason through this step by step. Produce exactly $targetSteps reasoning steps.Query: $query$contextLineFor each step, use this format:THOUGHT: [your reasoning]ACTION: [what you would do]OBSERVATION: [what you learn]CONFIDENCE: [0.0-1.0]Separate steps with --- on its own line.        """.trimIndent()    }    /**     * Parse the LLM response into [ReasoningStep] objects.     *     * Expects the format:     * ```     * THOUGHT: ...     * ACTION: ...     * OBSERVATION: ...     * CONFIDENCE: 0.85     * ---     * THOUGHT: ...     * ...     * ```     */    internal fun parseSteps(response: String): List<ReasoningStep> {        if (response.isBlank()) return emptyList()        val steps = mutableListOf<ReasoningStep>()        val blocks = response.split("---")        for (block in blocks) {            val trimmed = block.trim()            if (trimmed.isBlank()) continue            val thought = extractField(trimmed, "THOUGHT")            val action = extractField(trimmed, "ACTION")            val observation = extractField(trimmed, "OBSERVATION")            val confidenceText = extractField(trimmed, "CONFIDENCE")            val confidence = confidenceText?.toFloatOrNull()?.coerceIn(0f, 1f) ?: 0.8f            if (thought.isNotBlank()) {                steps.add(ReasoningStep(                    thought = thought,                    action = action.ifBlank { "Reasoning" },                    observation = observation.ifBlank { "N/A" },                    confidence = confidence,                ))            }        }        return steps.take(config.maxReasoningSteps)    }    /** Extract a field value from a text block (e.g., "THOUGHT: hello" → "hello"). */    private fun extractField(block: String, fieldName: String): String {        val regex = Regex("$fieldName:\\s*(.+)", RegexOption.IGNORE_CASE)        return regex.find(block)?.groupValues?.getOrNull(1)?.trim() ?: ""    }}/** * LLM interface for chain-of-thought reasoning. * * Real implementation wires to Module 4 (LlmProvider). Tests inject a fake. * * @param prompt the full reasoning prompt. * @param temperature LLM temperature (from persona's [LlmHyperparams]). * @return the raw reasoning text. */fun interface ReasoningLlm {    suspend fun reason(prompt: String, temperature: Float): String}